{
  "findings": [
    {
      "check_id": "CKV_GCP_38",
      "title": "Firewall rule allows all inbound traffic from any source",
      "resource": "google_compute_firewall.allow_http",
      "severity": "CRITICAL",
      "explanation": "The firewall rule allows inbound traffic from any source IP (0.0.0.0/0), potentially exposing the 'http-server' instances to unauthorized access."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http\" {\n  name    = \"digital-library-content-management-platform-firewall-http\"\n  network = google_compute_network.digital_library_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"80\", \"443\"]\n  }\n  source_ranges = [\"10.0.0.0/8\"]\n  target_tags   = [\"http-server\"]\n}",
  "fix_summary": "Restricted the source IP range for the firewall rule to a private network (10.0.0.0/8) to reduce exposure."
}
